# name: cross_set_lag1_agreement
# description: Proportion of consecutive trials (trial_index increases by 1, in row order) with different sets that receive the same response; observed above null means responses carry over between trials (participant bias/stickiness) that the independent-trial model lacks.
def test_statistic(df):
    r = df["rating"].values
    ti = df["trial_index"].values
    ns = df["number_set"].astype(str).values
    ok = (np.diff(ti) == 1) & (ns[1:] != ns[:-1])
    if not ok.any():
        return 0.0
    return float((r[1:] == r[:-1])[ok].mean())

# name: between_set_rate_dispersion
# description: Standard deviation across sets (with at least 20 trials) of the per-set yes rate; observed above null means people's overall willingness to say yes varies between sets more than the model's concept posterior produces.
def test_statistic(df):
    g = df.groupby("number_set")["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 20]
    if len(g) < 2:
        return 0.0
    return float(g["mean"].std())

# name: member_target_yes_rate
# description: Yes rate on trials whose target is one of the shown examples; observed below null means the model over-predicts endorsement of the examples themselves (too reliable), above means it under-predicts.
def test_statistic(df):
    s = df["number_set"].astype(str).str.split(",", expand=True).astype(float)
    t = df["target"].astype(float)
    m = s.eq(t, axis=0).any(axis=1).values
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].values[m].mean())
